<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import BackendLayout from '../components/BackendLayout.vue'
import BackendResource from './backend-resource.vue'
import TrafficVideo from '../components/TrafficVideo.vue'
import {backend,asPage} from '../services/backend'
import {backendResources,valueLabels} from '../data/backendResources'
const route=useRoute(),id=computed(()=>String(route.query.id||'')),tab=computed(()=>String(route.query.tab||'overview'))
const facility=ref<Record<string,any>>(),history=ref<any[]>([]),cameras=ref<any[]>([]),error=ref(''),loading=ref(false),operations=ref<InstanceType<typeof BackendResource>>()
let controller:AbortController|undefined
async function load(){controller?.abort();if(!id.value)return;const current=new AbortController();controller=current;loading.value=true;error.value='';try{facility.value=await backend('/api/underpasses/'+encodeURIComponent(id.value),{signal:current.signal});const results=await Promise.allSettled([backend('/api/underpasses/'+encodeURIComponent(id.value)+'/risk-scores?hours=6&limit=100',{signal:current.signal}),backend('/api/underpasses/'+encodeURIComponent(id.value)+'/cameras',{signal:current.signal})]);if(current.signal.aborted)return;if(results[0]?.status==='fulfilled')history.value=asPage<any>(results[0].value).items;if(results[1]?.status==='fulfilled')cameras.value=asPage<any>(results[1].value).items}catch(e){if(!current.signal.aborted)error.value=(e as Error).message}finally{if(!current.signal.aborted)loading.value=false}}
watch(id,load,{immediate:true});onBeforeUnmount(()=>controller?.abort())
const points=computed(()=>[...history.value].reverse().map((row,index)=>`${30+index*610/Math.max(1,history.value.length-1)},${180-Math.max(0,Math.min(100,Number(row.riskScore??row.score)||0))*1.5}`).join(' '))
function control(){if(facility.value)void operations.value?.open('action',facility.value,backendResources.facilities!.actions?.[facility.value.currentStatus==='BLOCKED'?1:0])}
</script>
<template><BackendLayout class="page-fac-detail"><section class="service-workspace restored-facility-detail"><div class="crumb">지하차도 관리 &gt; {{facility?.name||'시설 상세'}}</div><div class="page-head service-heading"><div><h1>{{facility?.name||'지하차도 상세'}} <span v-if="facility" class="badge" :class="facility.currentRiskLevel==='DANGER'?'danger':facility.currentRiskLevel==='WARNING'?'warn':'safe'">{{valueLabels[facility.currentRiskLevel]||'미확인'}}</span></h1><div class="sub">{{facility?.roadAddress}}</div></div><RouterLink class="btn" to="/fac-list">← 목록으로</RouterLink></div><p v-if="!id">지하차도 목록에서 시설을 선택해 주세요.</p><p v-if="error" role="alert" class="service-error">{{error}} <button @click="load">다시 시도</button></p><p v-if="loading" role="status">시설 정보를 불러오는 중입니다.</p><nav class="tabs" aria-label="지하차도 상세 탭"><RouterLink v-for="[value,label] in [['overview','개요'],['equip','설비'],['sign','전광판'],['cctv','CCTV'],['settings','설정']]" :key="value" :to="{path:'/fac-detail',query:{id,underpassId:id,tab:value}}" :class="{'is-current':tab===value}">{{label}}</RouterLink></nav>
<template v-if="facility"><section v-if="tab==='overview'" aria-label="개요"><div class="restored-overview-grid"><section class="card"><h2>위험 단계</h2><strong class="detail-score">{{facility.riskScore??facility.currentRiskScore??'—'}}점</strong><div class="restored-risk-gauge"><b :style="{width:Math.max(0,Math.min(100,Number(facility.riskScore??facility.currentRiskScore)||0))+'%'}"></b></div><dl class="service-detail"><dt>위험 단계</dt><dd>{{valueLabels[facility.currentRiskLevel]||'미확인'}}</dd><dt>강우량</dt><dd>{{facility.rainfallMm??'—'}} mm</dd></dl></section><section class="card"><h2>통제</h2><strong class="detail-score">{{facility.currentStatus==='BLOCKED'?'입구 차단 중':'정상 운영'}}</strong><dl class="service-detail"><dt>통과 중 차량</dt><dd>{{facility.remainingCount??'—'}}대</dd><dt>판별 대기</dt><dd>{{facility.pendingReviewCount??'—'}}건</dd></dl><button class="btn primary" @click="control">{{facility.currentStatus==='BLOCKED'?'통제 해제':'통제'}}</button></section><section class="card"><h2>위험 점수 추이 · 최근 6시간</h2><svg v-if="history.length" class="restored-risk-chart" viewBox="0 0 670 210" role="img" aria-label="관측된 위험 점수 추이"><path d="M30 20V180H640" fill="none" stroke="#8a93a0"/><polyline :points="points" fill="none" stroke="#2b5c8a" stroke-width="3"/></svg><p v-else>조회된 위험도 관측 기록이 없습니다.</p></section><section class="card"><h2>시설 정보</h2><dl class="service-detail"><dt>지역</dt><dd>{{facility.regionName||'—'}}</dd><dt>도로명 주소</dt><dd>{{facility.roadAddress||'—'}}</dd><dt>높이</dt><dd>{{facility.heightM??'—'}} m</dd><dt>길이</dt><dd>{{facility.lengthM??'—'}} m</dd></dl><RouterLink :to="{path:'/logs',query:{underpassId:id}}">최근 이벤트 · 통합 로그 →</RouterLink></section></div></section>
<BackendResource v-else-if="tab==='equip'" embedded resource-key="cameras"/>
<BackendResource v-else-if="tab==='sign'" embedded resource-key="display"/>
<section v-else-if="tab==='cctv'" class="restored-cctv"><div class="restored-overview-grid"><section v-for="camera in cameras" :key="camera.id" class="card"><h2>{{valueLabels[camera.cameraRole]||camera.cameraRole}} · {{camera.id}}</h2><TrafficVideo v-if="camera.streamUrl" :src="camera.streamUrl" hls/><p v-else>영상 주소가 등록되지 않았습니다.</p></section></div><p v-if="!cameras.length">등록된 카메라가 없습니다.</p><BackendResource embedded resource-key="transits"/></section>
<section v-else-if="tab==='settings'" class="restored-overview-grid"><section class="card"><h2>시설 정보</h2><dl class="service-detail"><dt>시설명</dt><dd>{{facility.name}}</dd><dt>도로명 주소</dt><dd>{{facility.roadAddress}}</dd></dl><button class="btn" @click="operations?.open('edit',facility)">시설 정보 수정</button><button class="btn" @click="operations?.open('action',facility,backendResources.facilities!.actions?.[3])">입출구 카메라 지정</button></section><section class="card"><BackendResource embedded resource-key="thresholds"/></section></section>
<div class="restored-facility-operations"><BackendResource ref="operations" operations-only embedded resource-key="facilities" @saved="load"/></div></template></section></BackendLayout></template>
